    if (applied.scopes === 'global_brands') {
      return dataFilters?.global_brands?.values || [];
    }
    if (applied.scopes === 'segment') {
      return dataFilters?.segments?.values || [];
    }
    return [];
  },

  time_frame: () => [],

  time_period: (dataFilters) => dataFilters?.time_period?.values || [],

  'ytd-month': (dataFilters) => dataFilters?.['ytd-month']?.values || [],

  distribution_scopes: (dataFilters) =>
    dataFilters?.distribution_scopes?.values || [],

  years: (dataFilters) => dataFilters?.years?.values || [],

  segments: (dataFilters) => dataFilters?.segments?.values || [],

  product_scope: (dataFilters) => dataFilters?.product_scope?.values || [],

  region: (dataFilters, applied) =>
    getRegionOptionsForCountry(dataFilters, applied?.country),

  channel: (dataFilters) =>
    Array.isArray(dataFilters?.channel?.values)
      ? dataFilters.channel.values
      : [],

  driver: (dataFilters) => dataFilters?.driver?.values || [],

  vehicle_level_1: (dataFilters, applied) =>
    getWatchTowerChildOptions(dataFilters, 'vehicle_level_1', applied.driver),

  vehicle_level_2: (dataFilters, applied) =>
    getWatchTowerChildOptions(
      dataFilters,
      'vehicle_level_2',
      applied.vehicle_level_1,
    ),

  vehicle_level_3: (dataFilters, applied) =>
    getWatchTowerChildOptions(
      dataFilters,
      'vehicle_level_3',
